constraint wolf_pos[1] = 0;
constraint goat_pos[1] = 0;
constraint cabbage_pos[1] = 0;
constraint boat_pos[1] = 0;

% Final positions: all on the destination shore
constraint wolf_pos[stage] = 1;
constraint goat_pos[stage] = 1;
constraint cabbage_pos[stage] = 1;
constraint boat_pos[stage] = 1;

% Constraints to ensure the wolf does not eat the goat and the goat does not eat the cabbage
constraint forall(i in 1..stage where boat_pos[i] != wolf_pos[i]) (
    goat_pos[i] != cabbage_pos[i]
);

% Constraints to ensure the boat can only carry the farmer and one item at a time
constraint forall(i in 1..(stage-1)) (
    (wolf_pos[i+1] = wolf_pos[i] \/ (wolf_pos[i+1] = boat_pos[i+1] /\ goat_pos[i+1] = goat_pos[i] /\ cabbage_pos[i+1] = cabbage_pos[i]))
