);

% Constraints to ensure the boat moves
constraint forall(i in 1..(stage-1)) (
    boat_pos[i+1] != boat_pos[i]
);

% Solve the problem
solve satisfy;

% Output the positions of the wolf, goat, cabbage, and boat at each stage
output [
    "{",
    join(",", [
        "\"" ++ "stages" ++ "\": [" ++ join(",", [
