Here is the MiniZinc model to solve this problem:

```minizinc
% Define the number of golfers, weeks, groups, and group size
int: num_golfers = 32;
int: n_weeks = 4;
int: n_groups = 3;
int: group_size = 3;

% Define the set of golfers
set of int: Golfers = 1..num_golfers;

% Define the set of weeks
set of int: Weeks = 1..n_weeks;

% Define the set of groups
set of int: Groups = 1..n_groups;

% Define the set of group members
set of int: GroupMembers = 1..group_size;

% Define the assignment of golfers to groups for each week
array[Weeks, Groups, GroupMembers] of var Golfers: assign;

% Constraint: Each golfer can only be in one group per week
constraint forall(w in Weeks) (
    alldifferent([assign[w, g, m] | g in Groups, m in GroupMembers])
);

% Constraint: No golfer plays in the same group with any other golfer more than once
constraint forall(w1 in Weeks, w2 in Weeks where w1 < w2, g1 in Groups, g2 in Groups) (
    alldifferent([assign[w1, g1, m1] | m1 in GroupMembers] ++ [assign[w2, g2, m2] | m2 in GroupMembers])
);

% Symmetry breaking: Order the groups in each week
constraint forall(w in Weeks, g in Groups where g < n_groups) (
    assign[w, g, 1] < assign[w, g + 1, 1] \/ 
    (assign[w, g, 1] = assign[w, g + 1, 1] /\ assign[w, g, 2] < assign[w, g + 1, 2]) \/
    (assign[w, g, 1] = assign[w, g + 1, 1] /\ assign[w, g, 2] = assign[w, g + 1, 2] /\ assign[w, g, 3] < assign[w, g + 1, 3])
);

% Symmetry breaking: Order the weeks
constraint forall(w in Weeks where w < n_weeks) (
    assign[w, 1, 1] < assign[w + 1, 1, 1] \/
    (assign[w, 1, 1] = assign[w + 1, 1, 1] /\ assign[w, 1, 2] < assign[w + 1, 1, 2]) \/
    (assign[w, 1, 1] = assign[w + 1, 1, 1] /\ assign[w, 1, 2] = assign[w + 1, 1, 2] /\ assign[w, 1, 3] < assign[w + 1, 1, 3])
);

% Output the assignments of golfers to groups for each week
output [
    "{",
    join(",", [
        "\"" ++ "week" ++ show(w) ++ "\": [" ++ join(",", [
            "[" ++ join(",", [show(assign[w, g, m]) | m in GroupMembers]) ++ "]" | g in Groups
        ]) ++ "]" | w in Weeks
    ]),
    "}"
