    [0, 4],
    [0, 5],
    [0, 4],
    [1, 3],
    [0, 2]
];

% Define the board as an array of variables
array[1..rows, 1..cols] of var 0..1: board;

% Helper function to check if a sequence of cells matches a rule
predicate match_rule(array[1..cols] of var 0..1: row, array[1..row_rule_len] of int: rule) =
    let {
        int: num_rules = sum(i in 1..row_rule_len)(rule[i] > 0);
        array[1..num_rules] of var 0..cols: block_starts;
        array[1..num_rules] of var 0..cols: block_ends;
        int: idx = 1;
    } in
    % Initialize block starts and ends
    block_starts[1] = 1,
    block_ends[num_rules] = cols,
    % Ensure blocks are non-overlapping and match the rule
