        block_starts[i] <= block_ends[i],
        block_ends[i] - block_starts[i] + 1 = rule[i],
        i < num_rules -> block_ends[i] + 1 < block_starts[i + 1]
    ),
    % Ensure the blocks match the row
    forall(i in 1..cols) (
        sum(j in 1..num_rules)(bool2int(block_starts[j] <= i /\ i <= block_ends[j])) = bool2int(row[i] = 1)
    );

% Apply row rules
