```minizinc
% Define the value of l
int: l = 9;
int: m = (l - 1) div 2;

% Define the variables a and b
array[1..l] of var {-1, 1}: a;
array[1..l] of var {-1, 1}: b;

% Define the periodic autocorrelation function (PAF)
function var int: paf(array[1..l] of var int: x, int: s) =
    sum(i in 1..l)(x[i] * x[(i + s - 1) mod l + 1]);

% Define the quadratic constraints
constraint forall(s in 1..m)(paf(a, s) + paf(b, s) = -2);

% Define the linear constraints
constraint sum(i in 1..l)(a[i]) = 1;
constraint sum(i in 1..l)(b[i]) = 1;

% Output the variables a and b
output [
    "{",
    join(",", [
        "\"" ++ "a" ++ "\": [" ++ join(",", [show(a[i]) | i in 1..l]) ++ "]",
        "\"" ++ "b" ++ "\": [" ++ join(",", [show(b[i]) | i in 1..l]) ++ "]"
    ]),
    "}"
];
```

