```minizinc
% Define the variables for the cost of each person's service
var int: paper_hanger;
var int: painter;
var int: plumber;
var int: electrician;
var int: carpenter;
var int: mason;

% Define the constraints based on the problem statement
constraint paper_hanger + painter = 1100;
constraint painter + plumber = 1700;
constraint plumber + electrician = 1100;
constraint electrician + carpenter = 3300;
constraint carpenter + mason = 5300;
